int fd = 4; // Open file descriptor
const char *name = "user.tag";
const char value[] = "important";
size_t size = sizeof(value);

// 1. Create attribute (fails if it already exists)
int flags_create = XATTR_CREATE;
int res = fsetxattr(fd, name, value, size, flags_create);

// 2. Replace attribute (fails if it does not exist)
int flags_replace = XATTR_REPLACE;
res = fsetxattr(fd, name, value, size, flags_replace);

// 3. Default (Create or Replace)
res = fsetxattr(fd, name, value, size, 0);

// res == -1 on error (check errno)
